mapper.update:
UPDATE TB_BBS_POST
TITLE = #{title}, CONTENT = #{content}, CATEGORY_CD = #{categoryCd}, NOTICE_YN = #{noticeYn}, NOTICE_START_DT = #{noticeStartDt}, NOTICE_END_DT = #{noticeEndDt}, SECRET_YN = #{secretYn}, SECRET_PWD = #{secretPwd}, ATCH_FILE_GRP_ID = #{atchFileGrpId}, MOD_USER_ID = #{modUserId}, MOD_DT = SYSDATE
WHERE POST_ID = #{postId}

UPDATE TB_BBS_POST
SET DEL_YN = 'Y',
    DEL_DT = SYSDATE,
    DEL_USER_ID = #{delUserId}
WHERE POST_ID = #{postId}

UPDATE TB_BBS_POST
SET VIEW_CNT = VIEW_CNT + 1
WHERE POST_ID = #{postId}

UPDATE TB_BBS_POST
SET LIKE_CNT = LIKE_CNT + 1
WHERE POST_ID = #{postId}

UPDATE TB_BBS_POST
SET COMMENT_CNT = (SELECT COUNT(*) FROM TB_BBS_COMMENT WHERE POST_ID = #{postId} AND DEL_YN = 'N')
WHERE POST_ID = #{postId}

mapper.select:
SELECT NVL(MAX(SORT_ORD), 0)
FROM TB_BBS_POST
WHERE GROUP_NO = #{groupNo}
